export const BODY: string = "\n<p>تصویر کو PDF میں بدلنا روزمرہ کے سب سے مفید فائل کاموں میں سے ایک ہے۔ تصویر دستاویز بن جاتی ہے، اسکین کا سیٹ ایک فائل بن جاتا ہے اور سب کچھ بھیجنے یا پرنٹ کرنے کے لیے تیار ہو جاتا ہے۔</p>\n<p>پورا طریقہ چند منٹ میں مکمل ہوتا ہے، لمبی دستاویز کے لیے بھی۔ آپ تصویریں اپ لوڈ کرتے ہیں، انہیں ترتیب دیتے ہیں، صفحہ سائز چنتے ہیں اور تیار PDF ڈاؤن لوڈ کر لیتے ہیں۔</p>\n<p>یہ رہنما ہر مرحلہ ترتیب سے بتاتا ہے، تاکہ آپ کی پہلی PDF صاف اور پیشہ ورانہ نکلے۔</p>\n<h2 id=\"gather-your-images\">مرحلہ 0: اپنی تصویریں جمع کریں اور تیار کریں</h2>\n<p>ٹول کھولنے سے پہلے ہر وہ تصویر جمع کریں جو دستاویز میں ہونی چاہیے۔ پاسپورٹ درخواست کے لیے مثال کے طور پر تصویر، دستخط اور اسکین شدہ فارم چاہیے ہو سکتے ہیں۔</p>\n<p>جانچیں کہ ہر تصویر درست طرف اوپر ہے۔ ٹیڑھا اسکین ٹیڑھا صفحہ بن جاتا ہے، اس لیے ٹیڑھی تصویریں پہلے گھمانے والے ٹول سے سیدھی کریں۔</p>\n<p>اپنے پاس موجود بہترین کوالٹی والے اصل استعمال کریں۔ دھندلا اسکین PDF کے اندر تیز نہیں ہوگا، اور کم ریزولوشن والی تصویر پرنٹ پر بدتر لگے گی۔</p>\n<h2 id=\"open-the-tool\">مرحلہ 1: Image to PDF ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/tasveer-se-pdf-banayein/\">Image to PDF ٹول</a> کھولیں۔ یہ صفحہ ونڈوز، میک، لینکس، کروم او ایس، اینڈرائیڈ اور آئی او ایس پر کام کرتا ہے، بغیر کچھ انسٹال کیے۔</p>\n<p>آپ کو اپ لوڈ والا حصہ اور نیچے دستاویز کی ترتیبات دکھائی دیں گی۔ ترتیبات کام کرتے ہوئے نظر آتی رہتی ہیں، اس لیے آپ انہیں تیار کرنے سے پہلے کسی بھی وقت بدل سکتے ہیں۔</p>\n<p>اکاؤنٹ کی ضرورت نہیں ہے، اور کچھ بھی اپ لوڈ نہیں ہوتا۔ PDF آپ کے آلے پر بنتی ہے، جو اس وقت اہم ہے جب تصویریں شناختی دستاویزات یا رسیدیں ہوں۔</p>\n<h2 id=\"upload-and-order\">مرحلہ 2: تصویریں اپ لوڈ کریں اور ترتیب طے کریں</h2>\n<p>اپنی تصویریں اپ لوڈ والے حصے پر گھسیٹ دیں، یا فائل پکر کھولنے کے لیے اس پر کلک کریں۔ آپ Ctrl+V سے اسکرین شاٹ سیدھا پیسٹ بھی کر سکتے ہیں، جو فوری دستاویزات کے لیے آسان ہے۔</p>\n<p>تصویریں Page Order فہرست میں اسی ترتیب سے دکھائی دیتی ہیں جس میں آپ نے انہیں شامل کیا تھا۔ کسی بھی صفحے کو اوپر یا نیچے گھسیٹ کر ترتیب درست کریں۔</p>\n<p>آپ بعد میں مزید تصویریں شامل کر سکتے ہیں، فہرست جانچنے کے بعد بھی۔ نئی تصویریں آخر میں شامل ہوتی ہیں، اور آپ انہیں باقی کی طرح اپنی جگہ پر گھسیٹتے ہیں۔</p>\n<h2 id=\"choose-page-size\">مرحلہ 3: صفحہ سائز چنیں</h2>\n<p>زیادہ تر دستاویزات کے لیے A4 چنیں۔ یہ دنیا کے زیادہ تر حصے میں معیاری صفحہ سائز ہے، اور سرکاری نظام فارم، درخواستوں اور اسکین شدہ کاغذات کے لیے اس کی توقع کرتے ہیں۔</p>\n<p>اگر وصول کنندہ امریکہ یا کینیڈا میں ہو، یا فارم خاص طور پر Letter سائز مانگے تو US Letter چنیں۔ فرق چھوٹا ہے مگر پرنٹ پر نظر آتا ہے۔</p>\n<p>جب PDF تصویر مجموعہ ہو تو Fit to Image Size چنیں۔ ہر صفحہ اپنی تصویر سے بالکل میل کھاتا ہے، بغیر سفید جگہ اور بغیر کراپ کے، جو البم اور اسکین آرکائیو کو سوٹ کرتا ہے۔</p>\n<h2 id=\"set-orientation\">مرحلہ 4: سمت اور جگہ طے کریں</h2>\n<p>Orientation کو Auto پر ہی چھوڑ دیں، جب تک بدلنے کی وجہ نہ ہو۔ Auto ہر تصویر پڑھتا ہے اور پورٹریٹ تصویر کو پورٹریٹ صفحہ اور لینڈ اسکیپ تصویر کو لینڈ اسکیپ صفحہ دیتا ہے۔</p>\n<p>اگر ہر تصویر ایک ہی شکل کی ہو تو یکساں دستاویز کے لیے Portrait یا Landscape مجبور کر سکتے ہیں۔ یکساں صفحے رسمی جمع کرائی کے لیے صاف لگتے ہیں۔</p>\n<p>Placement کے لیے دستاویزات کے لیے Contain چنیں۔ Contain پوری تصویر صفحے کے اندر فٹ کرتا ہے، اس لیے کوئی دستخط یا کونہ کبھی کراپ نہیں ہوتا۔</p>\n<h2 id=\"margins-and-quality\">مرحلہ 5: مارجن اور کوالٹی طے کریں</h2>\n<p>مقصد کے مطابق مارجن چنیں۔ No Margin مکمل صفحہ تصویروں کو سوٹ کرتا ہے، Small Margin عام دستاویزات کو سوٹ کرتا ہے اور Medium Margin پرنٹ کر کے فائل کرنے والی کسی بھی چیز کو سوٹ کرتا ہے۔</p>\n<p>یاد رکھیں کہ پرنٹر کاغذ کے بالکل کنارے تک پرنٹ نہیں کر سکتے۔ بغیر مارجن والی PDF کاغذ پر تصویر کا باریک حصہ کھو سکتی ہے، اس لیے پرنٹ کے لیے کم از کم چھوٹا مارجن استعمال کریں۔</p>\n<p>متن اور شناختی تصویروں کے لیے کوالٹی سلائیڈر اونچا طے کریں۔ چھوٹی چھپائی کم کوالٹی پر جلد دھندلی ہو جاتی ہے، اور دھندلی دستاویز مسترد ہو سکتی ہے۔</p>\n<h2 id=\"preview-and-check\">مرحلہ 6: پیش نظارہ دیکھیں اور سب کچھ جانچیں</h2>\n<p>Page Order فہرست ایک بار پھر دیکھیں۔ ترتیب، ہر صفحے کی سمت جانچیں اور یہ کہ کوئی صفحہ الٹا تو نہیں ہے۔</p>\n<p>یقین کریں کہ صفحہ سائز اور مارجن مقصد سے میل کھاتے ہیں۔ A4 مارجن والی فارم Fit to Image بغیر مارجن کے نہیں آنی چاہیے۔</p>\n<p>فائل نام ترتیب جانچیں۔ PDF کو صاف نام دیں، جیسے visa-documents.pdf، تاکہ وصول کنندہ کھولے بغیر جان لے کہ یہ کیا ہے۔</p>\n<h2 id=\"generate-and-download\">مرحلہ 7: PDF بنائیں اور ڈاؤن لوڈ کریں</h2>\n<p>Generate بٹن پر کلک کریں۔ پیش رفت پیغام Encoding page X of Y دکھاتا ہے، اس لیے آپ دستاویز کو صفحہ بہ صفحہ بنتا دیکھ سکتے ہیں۔</p>\n<p>بنانے میں مختصر دستاویز کے لیے چند سیکنڈ اور لمبی کے لیے تھوڑا زیادہ وقت لگتا ہے۔ بیس صفحے عام طور پر آدھے منٹ سے کم میں مکمل ہو جاتے ہیں۔</p>\n<p>جب ڈاؤن لوڈ ڈائیلاگ دکھائی دے تو فائل محفوظ کریں۔ اگر ڈائیلاگ آپ کے دیکھنے سے پہلے غائب ہو جائے تو Downloads فولڈر جانچیں، کیونکہ فائل وہاں خود بخود محفوظ ہو جاتی ہے۔</p>\n<ol>\n<li>Image to PDF ٹول کھولیں اور اپنی تصویریں اپ لوڈ کریں۔</li>\n<li>صفحے درست ترتیب میں لگائیں۔</li>\n<li>صفحہ سائز، سمت، مارجن اور کوالٹی چنیں۔</li>\n<li>PDF بنائیں اور بھیجنے سے پہلے جانچیں۔</li>\n</ol>\n<h2 id=\"converting-a-single-photo\">ایک تصویر کو PDF میں بدلنا</h2>\n<p>ایک تصویر انہی مرحلوں سے ایک صفحے والی PDF بن جاتی ہے۔ تصویر اپ لوڈ کریں، صفحہ سائز چنیں اور بنائیں۔</p>\n<p>ایک تصویر کے لیے Fit to Image Size اکثر بہترین انتخاب ہے۔ صفحہ تصویر سے بالکل میل کھاتا ہے، بغیر سفید کناروں اور بغیر ضائع شدہ جگہ کے۔</p>\n<p>ایک تصویر والی PDF کسی کو تصویر بھیجنے کے لیے مفید ہے جسے دستاویز فارمیٹ چاہیے۔ کچھ فارم صرف PDF اپ لوڈ قبول کرتے ہیں، اور یہ تعمیل کا تیز ترین طریقہ ہے۔</p>\n<h2 id=\"converting-scans\">اسکین شدہ دستاویزات بدلنا</h2>\n<p>اسکین سب سے عام PDF کام ہیں۔ کئی صفحوں والا فارم، معاہدہ یا رسیدوں کا سیٹ ایک صاف دستاویز بن جاتا ہے۔</p>\n<p>اسکین کے لیے A4 صفحہ سائز اور Contain جگہ استعمال کریں۔ یہ مجموعہ ہر لفظ نظر آنے والا اور ہر صفحہ ایک سائز کا رکھتا ہے۔</p>\n<p>اسکین کے لیے کوالٹی سلائیڈر اونچا رکھیں۔ چھوٹی چھپائی اور دستخط کم کوالٹی پر دھندلے ہو جاتے ہیں، اور دھندلا اسکین وصول کرنے والا دفتر مسترد کر سکتا ہے۔</p>\n<h2 id=\"fixing-common-problems\">عام مسائل کا حل</h2>\n<p>اگر کوئی صفحہ ٹیڑھا نکلے تو ماخذ تصویر ٹیڑھی تھی۔ شامل کرنے سے پہلے تصویر گھمائیں، یا اسے ہٹا کر گھما کر دوبارہ شامل کریں۔</p>\n<p>اگر PDF ای میل کے لیے بہت بڑی ہو تو کوالٹی سلائیڈر ایک درجہ کم کریں اور دوبارہ بنائیں۔ تصویریں درمیانی کوالٹی پر اچھی کمپریس ہوتی ہیں، جبکہ اسکین کو نرم ہاتھ چاہیے ہوتا ہے۔</p>\n<p>اگر کوئی صفحہ کراپ ہو تو آپ نے شاید Cover جگہ چنی تھی۔ Contain پر جائیں اور دوبارہ بنائیں، اور پوری تصویر فٹ ہو جائے گی۔</p>\n<h2 id=\"mobile-tips\">فون اور ٹیبلٹ کے لیے نکات</h2>\n<p>فون پر اپ لوڈ والے حصے پر ٹیپ کریں اور گیلری سے تصویریں چنیں۔ آپ کئی تصویریں ایک ساتھ چن سکتے ہیں، اور وہ اسی ترتیب میں آتی ہیں جس میں آپ نے انہیں چنا تھا۔</p>\n<p>ترتیب بدلنے کے لیے ترتیب فہرست میں صفحے انگلی سے گھسیٹیں۔ فہرست ٹچ کے لیے موزوں ہے، اور لمبا دبانا عام طور پر گھسیٹ شروع کر دیتا ہے۔</p>\n<p>ڈاؤن لوڈ آپ کے فون کے Downloads فولڈر میں آتے ہیں۔ آئی فون پر Files ایپ کھولیں، اینڈرائیڈ پر اپنا فائل مینیجر کھولیں۔</p>\n<h2 id=\"receipts-for-expenses\">اخراجات کے لیے رسیدیں بدلنا</h2>\n<p>اخراجات کے دعووں کو رسیدیں چاہییں ہوتی ہیں، اور رسیدوں کی PDF تصویروں کے فولڈر سے کہیں صاف ہوتی ہے۔ فی سفر یا مہینہ ایک دستاویز مالیات ٹیم کو خوش رکھتی ہے۔</p>\n<p>ہر رسید چپٹی، اچھی روشنی میں اور بغیر سائے کے فوٹوگراف کریں۔ ٹیڑھی یا سایہ دار رسید پڑھنا مشکل ہوتا ہے، اور مالیات ٹیم اسے مسترد کر سکتی ہے۔</p>\n<p>A4 صفحہ سائز Contain جگہ کے ساتھ استعمال کریں، تاکہ ہر رسید اپنے صفحے پر مکمل فٹ ہو۔ کٹی ہوئی کل یا گم شدہ تاریخ مسترد شدہ دعوے کی سب سے عام وجہ ہے۔</p>\n<h2 id=\"portfolio-pdf\">پورٹ فولیو PDF بنانا</h2>\n<p>پورٹ فولیو PDF آپ کا بہترین کام ایک دستاویز میں دکھاتا ہے جسے کوئی بھی کھول سکتا ہے۔ ڈیزائنر، فوٹوگرافر اور فری لانسر سب کلائنٹ جیتنے کے لیے اسے استعمال کرتے ہیں۔</p>\n<p>پہلے اپنی مضبوط ترین تصویریں چنیں، پھر انہیں سوچے سمجھے ترتیب میں لگائیں۔ پہلا صفحہ آپ کا بہترین کام ہونا چاہیے، کیونکہ یہ اس کے بعد سب کچھ کا تاثر طے کرتا ہے۔</p>\n<p>پورٹ فولیو کے لیے Fit to Image Size استعمال کریں، تاکہ ہر تصویر اپنا صفحہ بغیر سفید کناروں کے بھرے۔ مکمل بھرے لے آؤٹ چھپی کتاب کی طرح سوچا سمجھا اور پیشہ ورانہ محسوس ہوتا ہے۔</p>\n<h2 id=\"photos-and-scans-together\">ایک PDF میں تصویریں اور اسکین ملانا</h2>\n<p>حقیقی دستاویزات اکثر تصویریں اور اسکین ملاتی ہیں۔ ویزا درخواست میں JPG تصویر، پاسپورٹ کا PNG اسکین اور بینک اسٹیٹمنٹ کا JPG اسکین ہو سکتا ہے۔</p>\n<p>PDF بنانے والا ایک دستاویز میں ملے جلے فارمیٹ قبول کرتا ہے۔ ہر صفحہ اپنا ماخذ فارمیٹ رکھتا ہے، اس لیے آپ کو پہلے سب کچھ ایک فارمیٹ میں بدلنے کی ضرورت نہیں ہوتی۔</p>\n<p>صفحے منطقی ترتیب میں لگائیں، شناختی دستاویزات پہلے اور معاون ثبوت بعد میں۔ صاف ترتیب قاری کو درخواست کی کہانی سمجھنے میں مدد کرتی ہے۔</p>\n<h2 id=\"sending-the-pdf\">PDF کسی اور کو بھیجنا</h2>\n<p>بھیجنے سے پہلے تیار PDF کھولیں اور اسے وصول کنندہ کی طرح پڑھیں۔ صفحہ گنتی، ترتیب جانچیں اور یہ کہ سب سے چھوٹا متن پڑھنے کے قابل ہے۔</p>\n<p>ای میل کے لیے PDF سیدھا منسلک کریں اگر وہ سائز حد سے نیچے ہو۔ زیادہ تر خدمات 20 MB سے 25 MB دیتی ہیں، اور اچھی بنی PDF عام طور پر اس سے کہیں چھوٹی ہوتی ہے۔</p>\n<p>بڑی PDF کے لیے کلاؤڈ اسٹوریج پر اپ لوڈ کریں اور لنک شیئر کریں۔ وصول کنندہ فائل بغیر کسی سائز مسئلے کے ڈاؤن لوڈ کرتا ہے، اور آپ بعد میں لنک واپس لے سکتے ہیں۔</p>\n<h2 id=\"id-photos-applications\">درخواستوں کے لیے شناختی تصویریں بدلنا</h2>\n<p>درخواست فارموں کو اکثر شناختی تصویر PDF صفحے کے طور پر چاہیے ہوتی ہے، اور تصویر صاف ہونی چاہیے۔ دھندلی شناختی تصویر درخواست کو ہفتوں تاخیر کر سکتی ہے، اس لیے تبدیلی احتیاط کی مستحق ہے۔</p>\n<p>سادہ پس منظر والی حالیہ، اچھی روشنی والی تصویر استعمال کریں۔ چہرہ سامنے کی طرف ہونا چاہیے، بغیر سائے اور بغیر دھوپ کے چشمے کے، درخواست کے تصویر اصولوں کے مطابق۔</p>\n<p>A4 صفحہ سائز Contain جگہ کے ساتھ چنیں، تاکہ پوری تصویر صفحے پر فٹ ہو۔ کٹی ہوئی ٹھوڑی یا پیشانی مسترد شدہ شناختی تصویر کی سب سے عام وجہ ہے۔</p>\n<p>پورا طریقہ یہی ہے، ڈھیلی تصویروں کے سیٹ سے ایک صاف PDF تک۔ گہری وضاحت کے لیے <a href=\"/ur/blog/tasveer-se-pdf-rehnumai/\">Image to PDF: Complete Guide</a> پڑھیں، اور فارمیٹ انتخاب کے لیے <a href=\"/ur/blog/jpg-se-pdf-vs-png-se-pdf/\">JPG to PDF vs PNG to PDF</a> دیکھیں۔ اگر آپ کی تصویریں آئی فون کی HEIC فائلیں ہیں تو <a href=\"/ur/heic-ko-jpg-mein-convert-karein/\">HEIC to JPG کنورٹر</a> انہیں پہلے تیار کر سکتا ہے۔</p>\n";

